# hypothesis: a class that leaves an abstract property unimplemented cannot be instantiated, so checkers should flag Blob() and CPython should raise TypeError, while a concrete property override is accepted.
from abc import ABC, abstractmethod
from typing import reveal_type


class Shape(ABC):
    @property
    @abstractmethod
    def sides(self) -> int:
        ...

    @abstractmethod
    def area(self) -> float:
        ...


class Square(Shape):
    def __init__(self, side: float) -> None:
        self.side = side

    @property
    def sides(self) -> int:
        return 4

    def area(self) -> float:
        return self.side * self.side


class Blob(Shape):
    def area(self) -> float:
        return 0.0


def describe(s: Shape) -> str:
    return f'{s.sides} sides, area {s.area()}'


def probe() -> None:
    sq = Square(2.0)
    reveal_type(sq.sides)
    assert sq.sides == 4
    assert sq.area() == 4.0
    assert describe(sq) == '4 sides, area 4.0'
    caught = False
    try:
        Blob()  # expect-error
    except TypeError:
        caught = True
    assert caught


probe()
